import sys

MOD = 10**9 + 7

def main():
    n, m = map(int, sys.stdin.read().split())
    top = n + 20
    fact = [1] * (top + 1)
    for i in range(1, top + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv = [1] * (top + 1)
    inv[top] = pow(fact[top], MOD - 2, MOD)
    for i in range(top, 0, -1):
        inv[i - 1] = inv[i] * i % MOD

    def comb(a, b):
        return fact[a] * inv[b] % MOD * inv[a - b] % MOD

    spf = list(range(m + 1))
    i = 2
    while i * i <= m:
        if spf[i] == i:
            for j in range(i * i, m + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    total = 0
    for v in range(1, m + 1):
        x = v
        ways = 1
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            ways = ways * comb(n + e - 1, e) % MOD
        total = (total + ways) % MOD
    print(total)

main()

